import 'package:flutter/material.dart';import 'package:intl/intl.dart';import '../models/finance_models.dart';import '../services/database_service.dart';import '../services/finance_calculator.dart';
class PayrollScreen extends StatefulWidget{const PayrollScreen({super.key});@override State<PayrollScreen> createState()=>_PayrollScreenState();}
class _PayrollScreenState extends State<PayrollScreen>{
 List<EmployeeRecord> employees=[];List<PayrollPayment> payments=[];bool loading=true;
 @override void initState(){super.initState();load();}
 Future<void> load()async{final a=await DatabaseService.instance.employees();final p=await DatabaseService.instance.payroll();if(mounted)setState((){employees=a;payments=p;loading=false;});}
 Future<void> addEmployee()async{final name=TextEditingController(),wage=TextEditingController();String type='daily';final ok=await showDialog<bool>(context:context,builder:(d)=>StatefulBuilder(builder:(d,s)=>AlertDialog(title:const Text('Add employee'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Employee name')),DropdownButtonFormField<String>(value:type,items:const[DropdownMenuItem(value:'daily',child:Text('Daily wage')),DropdownMenuItem(value:'monthly',child:Text('Monthly salary'))],onChanged:(v)=>s(()=>type=v??'daily')),TextField(controller:wage,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Wage / salary'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Add'))])));final v=double.tryParse(wage.text);if(ok==true&&name.text.trim().isNotEmpty&&v!=null&&v>0){await DatabaseService.instance.addEmployee(EmployeeRecord(id:null,name:name.text.trim(),type:type,wage:v));await load();}name.dispose();wage.dispose();}
 Future<void> pay(EmployeeRecord e)async{final amount=TextEditingController(text:e.wage.toStringAsFixed(2));final now=DateTime.now();final period=e.type=='daily'?DateFormat('yyyy-MM-dd').format(now):DateFormat('yyyy-MM').format(now);if(payments.any((p)=>p.employeeId==e.id&&p.period==period)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Payment already recorded for this period.')));return;}final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:Text('Pay ${e.name}'),content:TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Payment amount')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Confirm'))]));final v=double.tryParse(amount.text);if(ok==true&&v!=null&&v>0){await DatabaseService.instance.addPayroll(PayrollPayment(id:null,employeeId:e.id!,date:now,period:period,amount:v,type:e.type));await DatabaseService.instance.addExpense(ExpenseRecord(id:null,date:now,category:e.type=='daily'?'Salary-Daily':'Salary-Monthly',amount:v,description:'Payroll paid to ${e.name}'));await load();}amount.dispose();}
 @override Widget build(BuildContext c){final month=DateFormat('yyyy-MM').format(DateTime.now());final total=payments.where((p)=>p.period==month).fold<double>(0,(s,p)=>s+p.amount);return Scaffold(appBar:AppBar(title:const Text('Payroll'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:addEmployee,icon:const Icon(Icons.person_add),label:const Text('Add employee')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(children:[const Expanded(child:Text('Payroll this month',style:TextStyle(fontWeight:FontWeight.w700))),Text(FinanceCalculator.money(total),style:const TextStyle(fontWeight:FontWeight.w800,fontSize:18))]))),Text('${employees.length} active employees',style:Theme.of(c).textTheme.titleMedium),...employees.map((e){final now=DateTime.now();final period=e.type=='daily'?DateFormat('yyyy-MM-dd').format(now):month;final paid=payments.any((p)=>p.employeeId==e.id&&p.period==period);return Card(child:ListTile(leading:CircleAvatar(child:Text(e.name[0].toUpperCase())),title:Text(e.name),subtitle:Text('${e.type=='daily'?'Daily wage':'Monthly salary'} • ${FinanceCalculator.money(e.wage)}'),trailing:FilledButton(onPressed:paid?null:()=>pay(e),child:Text(paid?'Paid':'Pay'))));}),const Divider(),Text('Recent payments',style:Theme.of(c).textTheme.titleMedium),...payments.take(25).map((p)=>ListTile(title:Text(p.type=='daily'?'Daily wage payment':'Monthly salary payment'),subtitle:Text('${DateFormat('dd MMM yyyy').format(p.date)} • ${p.period}'),trailing:Text(FinanceCalculator.money(p.amount))))]));}
}
